    title: "DOM Manipulation in JavaScript",
    aim: "To demonstrate how to manipulate HTML elements dynamically using JavaScript and the Document Object Model (DOM).",
    files: [
      {
        name: "program3.html",
        code: `<html>
<head>
<title> DOM Manipulation </title>
</head>
<body>
<h2 id="heading"> Welcome to my page </h2>
<p id="info"> Click the button to change this content and color.</p>
<button onclick="manipulateDOM()"> Click here </button>
<br><br>
<script>
function manipulateDOM() {
var heading = document.getElementById("heading");
heading.innerHTML = "<u> Content Changed! </u>";
heading.style.color = "green";
heading.style.fontSize = "30px";
var info = document.getElementById("info");
info.innerHTML = "<b> This is updated using JavaScript! </b>";
info.style.backgroundColor = "lightyellow";
}
</script>
</body>
</html>`
      }
    ]
  }
];

/* ---------- Helpers ---------- */
function escapeHtml(str){
  return str.replace(/&/g,'&amp;')
            .replace(/</g,'&lt;')
            .replace(/>/g,'&gt;');
}
function buildLineNumbers(code){
  const lines = code.split('\n').length;
  let nums = '';
  for(let i=1;i<=lines;i++){
    nums+=i+'\\n';
  }
  return nums;
}

/* ---------- UI Rendering ---------- */
const listEl = document.getElementById('programList');

programs.forEach((prog,i)=>{
  const row = document.createElement('div');
  row.className='row';
  row.dataset.idx=i;

  const left = document.createElement('div');
  left.className='left';
  left.innerHTML = `<span class="num">${prog.num}</span>
                    <span class="title">${prog.title}</span>
                    <span class="chips">${prog.files.map(f=>`<span class="chip">${f.name}</span>`).join(' ')}</span>`;
  const arrow = document.createElement('div');
  arrow.className='arrow';
  arrow.innerHTML='&#9654;'; // right-pointing triangle

  row.appendChild(left);
  row.appendChild(arrow);
  listEl.appendChild(row);

  const acc = document.createElement('div');
  acc.className='accordion';
  acc.style.display='none';
  const content = document.createElement('div');
  content.className='section';
  content.innerHTML = `<strong>Aim:</strong> ${prog.aim}`;
  acc.appendChild(content);

  // tabs if >1 file
  const tabsDiv = document.createElement('div');
  tabsDiv.className='tabs';
  prog.files.forEach((file,fi)=>{
    const tab = document.createElement('div');
    tab.className='tab';
    tab.textContent=file.name;
    tab.dataset.fileIdx=fi;
    if(fi===0) tab.classList.add('active');
    tabsDiv.appendChild(tab);
  });
  acc.appendChild(tabsDiv);

  // code box
  const codeWrap = document.createElement('div');
  codeWrap.className='code-wrapper';
  const codeBox = document.createElement('div');
  codeBox.className='code-box';
  const linenums = document.createElement('pre');
  linenums.className='linenums';
  const codeContent = document.createElement('pre');
  codeContent.className='code-content';
  codeBox.appendChild(linenums);
  codeBox.appendChild(codeContent);
  codeWrap.appendChild(codeBox);
  acc.appendChild(codeWrap);

  // footer + buttons
  const footer = document.createElement('div');
  footer.className='footer';
  const leftFoot = document.createElement('div');
  leftFoot.innerHTML = `<span class="linecnt"></span> | UTF-8`;
  const rightFoot = document.createElement('div');
  rightFoot.innerHTML = `<button class="btn saveBtn"></button>
                         <button class="btn copyBtn">Copy code</button>
                         <span class="msg"></span>`;
  footer.appendChild(leftFoot);
  footer.appendChild(rightFoot);
  acc.appendChild(footer);

  // run instructions
  const runInfo = document.createElement('div');
  runInfo.className='run-info';
  acc.appendChild(runInfo);

  // ZIP button (only for program 2)
  let zipBtn = null;
  if(prog.files.length>1){
    zipBtn = document.createElement('button');
    zipBtn.className='btn zipBtn';
    zipBtn.textContent='Save both files (.zip)';
    rightFoot.appendChild(zipBtn);
  }

  listEl.appendChild(acc);

  // ----- State handling -----
  function showFile(idx){
    const file = prog.files[idx];
    const escaped = escapeHtml(file.code);
    codeContent.innerHTML = escaped;
    linenums.textContent = buildLineNumbers(file.code);
    // update save button text
    const saveBtn = rightFoot.querySelector('.saveBtn');
    saveBtn.textContent = `Save ${file.name}`;
    // line count
    leftFoot.querySelector('.linecnt').textContent = file.code.split('\\n').length + ' lines';
    // run info
    if(prog.files.length===1){
      runInfo.textContent = `To run: Save the file, then double‑click it. It opens in your browser. To edit it, right‑click the file and choose Open with, then Notepad.`;
    }else{
      runInfo.textContent = `To run: Save both files in the same folder, then double‑click index.html. It opens in your browser. To edit a file, right‑click it and choose Open with, then Notepad.`;
    }
    // clear message
    rightFoot.querySelector('.msg').textContent = '';
  }

  // initialise first file
  showFile(0);

  // tab clicks
  tabsDiv.addEventListener('click', e=>{
    if(e.target.classList.contains('tab')){
      const idx = Number(e.target.dataset.fileIdx);
      tabsDiv.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));
      e.target.classList.add('active');
      showFile(idx);
    }
  });

  // save button
  rightFoot.querySelector('.saveBtn').addEventListener('click',()=>{
    const activeIdx = Number(tabsDiv.querySelector('.tab.active').dataset.fileIdx);
    const file = prog.files[activeIdx];
    const blob = new Blob([file.code],{type:'text/plain'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = file.name;
    a.click();
    rightFoot.querySelector('.msg').textContent = `Saved ${file.name}.`;
  });

  // copy button
  rightFoot.querySelector('.copyBtn').addEventListener('click', async()=>{
    const activeIdx = Number(tabsDiv.querySelector('.tab.active').dataset.fileIdx);
    const txt = prog.files[activeIdx].code;
    try{
      await navigator.clipboard.writeText(txt);
      rightFoot.querySelector('.msg').textContent = 'Copied to clipboard.';
    }catch(err){
      // fallback
      const ta = document.createElement('textarea');
      ta.value = txt;
      document.body.appendChild(ta);
      ta.select();
      try{
        document.execCommand('copy');
        rightFoot.querySelector('.msg').textContent = 'Copied via fallback.';
      }catch(e){
        rightFoot.querySelector('.msg').textContent = 'Press Ctrl+C to copy.';
      }
      document.body.removeChild(ta);
    }
  });

  // zip button (program 2 only)
  if(zipBtn){
    zipBtn.addEventListener('click',()=>{ createAndDownloadZip(prog.files, 'program2.zip'); });
  }

  // row click – accordion toggle
  row.addEventListener('click',()=> {
    const currentlyOpen = document.querySelector('.row.open');
    if(currentlyOpen && currentlyOpen!==row){
      // close previous
      currentlyOpen.classList.remove('open');
      currentlyOpen.nextElementSibling.style.display='none';
    }
    const isOpen = row.classList.toggle('open');
    acc.style.display = isOpen ? 'block' : 'none';
  });

  // open first program on load
  if(i===0){
    row.click();
  }
});

/* ---------- ZIP generation (store‐only, no compression) ---------- */
function crc32(str){
  const table = new Uint32Array(256).map((_,i)=>{
    let c = i;
    for(let j=0;j<8;j++){
      c = ((c & 1) ? 0xEDB88320 ^ (c>>>1) : c>>>1) >>>0;
    }
    return c>>>0;
  });
  let crc = 0xFFFFFFFF;
  const bytes = new TextEncoder().encode(str);
  for(let b of bytes){
    crc = (crc>>>8) ^ table[(crc ^ b) & 0xFF];
  }
  return (crc ^ 0xFFFFFFFF) >>>0;
}
function createAndDownloadZip(files, zipName){
  const encoder = new TextEncoder();
  const parts = [];
  let localOffset = 0;
  const central = [];

  files.forEach(f=>{
    const data = encoder.encode(f.code);
    const crc = crc32(f.code);
    const header = new Uint8Array(30);
    // local file header signature
    header.set([0x50,0x4b,0x03,0x04],0);
    // version needed to extract
    header.set([0x14,0x00],4);
    // general purpose bit flag
    header.set([0x00,0x00],6);
    // compression method (0 = store)
    header.set([0x00,0x00],8);
    // file mod time/date (zero)
    header.set([0x00,0x00,0x00,0x00],10);
    // CRC-32
    header[14]=crc&0xFF; header[15]=(crc>>>8)&0xFF; header[16]=(crc>>>16)&0xFF; header[17]=(crc>>>24)&0xFF;
    // compressed size
    header[18]=data.length&0xFF; header[19]=(data.length>>>8)&0xFF; header[20]=(data.length>>>16)&0xFF; header[21]=(data.length>>>24)&0xFF;
    // uncompressed size (same)
    header[22]=data.length&0xFF; header[23]=(data.length>>>8)&0xFF; header[24]=(data.length>>>16)&0xFF; header[25]=(data.length>>>24)&0xFF;
    // file name length
    const nameBytes = encoder.encode(f.name);
    header[26]=nameBytes.length&0xFF; header[27]=(nameBytes.length>>>8)&0xFF;
    // extra field length = 0
    header[28]=0; header[29]=0;
    parts.push(header);
    parts.push(nameBytes);
    parts.push(data);
    // central directory header
    const cHeader = new Uint8Array(46);
    cHeader.set([0x50,0x4b,0x01,0x02],0);
    cHeader.set([0x14,0x00],4); // version made by
    cHeader.set(header.subarray(4,30),6); // copy from local header
    // file comment length
    cHeader[44]=0; cHeader[45]=0;
    parts.push(cHeader);
    parts.push(nameBytes);
    // record offset
    central.push({offset:localOffset});
    localOffset += header.length + nameBytes.length + data.length + cHeader.length + nameBytes.length;
  });

  // End of central directory record
  const eocd = new Uint8Array(22);
  eocd.set([0x50,0x4b,0x05,0x06],0);
  eocd.set([0x00,0x00,0x00,0x00],4); // number of this disk, disk with start
  const totalEntries = files.length;
  eocd[8]=totalEntries&0xFF; eocd[9]=(totalEntries>>>8)&0xFF;
  eocd[10]=totalEntries&0xFF; eocd[11]=(totalEntries>>>8)&0xFF;
  // size of central dir
  const centralSize = files.reduce((s,f,i)=>s + 46 + encoder.encode(f.name).length,0);
  eocd[12]=centralSize&0xFF; eocd[13]=(centralSize>>>8)&0xFF; eocd[14]=(centralSize>>>16)&0xFF; eocd[15]=(centralSize>>>24)&0xFF;
  // offset of central dir
  const centralOffset = localOffset - centralSize;
  eocd[16]=centralOffset&0xFF; eocd[17]=(centralOffset>>>8)&0xFF; eocd[18]=(centralOffset>>>16)&0xFF; eocd[19]=(centralOffset>>>24)&0xFF;
  eocd[20]=0; eocd[21]=0; // comment length

  parts.push(eocd);
  const blob = new Blob(parts,{type:'application/zip'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = zipName;
  a.click();
}

/* ---------- End of script ---------- */
</script>
</body>
</html>
```

### How to use it

1. **Open** the file by double‑clicking it – it works completely offline.  
2. The list of programs appears; the first one is already expanded.  
3. Click any row to expand it (only one row stays open at a time).  
4. Inside an expanded program you can:  
   * **Save** the displayed file (`Save <filename>`).  
   * **Copy** the code to the clipboard (`Copy code`).  
   * For Program 2, you also get **“Save both files (.zip)”** which creates a ZIP containing `index.html` and `styles.css`.  
5. After a save or copy, a short feedback message appears next to the buttons.  

> **Important note:** A web page cannot launch Notepad (or any other desktop application) directly for security reasons. The *Save* and *Copy* buttons are the way you retrieve the code so you can open it later with Notepad or any editor you prefer.

