/* ---------- Global ---------- */
html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);font-family:"IBM Plex Sans", system-ui, "Segoe UI", sans-serif;}
.container{max-width:860px;margin:auto;padding:0 1rem;}
.topline{font-size:0.85rem;color:var(--muted);text-transform:uppercase;}
h1{margin:0.4rem 0;font-weight:600;}
.intro{margin:.4rem 0;font-size:0.95rem;color:var(--muted);}
.program-list{display:flex;flex-direction:column;gap:0.6rem;}
