.tab{padding:.4rem .8rem;cursor:pointer;flex-shrink:0;}
.tab[aria-selected="true"]{background:var(--code-bg);font-weight:600;}
.code-box{position:relative;overflow:auto;font-family:"IBM Plex Mono", Consolas, "Courier New", monospace;font-size:13.5px;line-height:1.65;white-space:pre;}
.code-line{display:block;padding-left:2.5rem;}
.code-line::before{counter-increment:ln;content:counter(ln);position:absolute;left:0;width:2rem;text-align:right;color:var(--gutter);user-select:none;}
.code-box{counter-reset:ln;}
.code-footer{display:flex;justify-content:space-between;padding:.3rem .6rem;font-size:0.75rem;background:var(--surface);border-top:1px solid var(--line);} 
